    <div class="mx-auto max-w-6xl" x-data="{
        hargaSatuan: 0, qty: 1, dp: 0, tenor: 1, bunga: 0, pelangganAlamat: '',
        pilihBarang(event) { this.hargaSatuan = Number(event.target.selectedOptions[0]?.dataset.harga || 0) },
        pilihPelanggan(event) { this.pelangganAlamat = event.target.selectedOptions[0]?.dataset.alamat || '' },
        get harga() { return this.hargaSatuan * Number(this.qty || 0) },
        get pokok() { return Math.max(this.harga - Number(this.dp || 0), 0) },
        get margin() { return this.pokok * (Number(this.bunga || 0) / 100) * Number(this.tenor || 0) },
        get total() { return this.pokok + this.margin },
        get angsuran() { return this.tenor ? Math.round(this.total / Number(this.tenor)) : 0 },
        rupiah(nilai) { return new Intl.NumberFormat('id-ID', {maximumFractionDigits:0}).format(nilai || 0) }
    }">
